      (1, 3294, 3, '419E1781', '4151790651', null, '2021-03-04', '2021-03-04 13:23:23', '2021-03-04', 118, 118, 'REGISTRO DE FC', 1016, 32.95, 7.7, 'V', 'JDL', null, null, 'JDL', '2021-03-04 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2021, null, 3, 0, 0, 0, null, null, null, null, 'C', true, 10, 2, null, null),
